        $selectedPayableAmount = max($selectedBasePrice - $selectedDiscountAmount, 0);
        $qrNote = trim('TEACHER ' . ($selectedCouponCode ?: 'REGISTER'));
        $countdownEndsAt = $couponPreview['expires_at'] ?? (($application && $application->status === 'pending_payment' && $application->submitted_at) ? $application->submitted_at->copy()->addMinutes(30)->toIso8601String() : null);
    @endphp

