        .teacher-apply-intro p {
            max-width: 760px;
            color: var(--text-color-muted, #64748b);
        }

        .teacher-apply-login-note {
            margin-top: 1rem;
            padding: 1rem 1.15rem;
            border-radius: 18px;
            background: rgba(15, 23, 42, 0.05);
        }

        html[data-theme="dark"] .teacher-apply-login-note {
            background: rgba(148, 163, 184, 0.1);
        }

        .teacher-apply-card {
            padding: 1.5rem;
            border-radius: 28px;
            background: var(--card-bg-color, #fff);
            box-shadow: 0 18px 50px rgba(15, 23, 42, 0.08);
        }

        .teacher-package-select {
            display: block;
            height: 100%;
            padding: 1.2rem;
            border-radius: 24px;
            border: 1px solid rgba(37, 99, 235, 0.14);
            background: linear-gradient(180deg, rgba(37, 99, 235, 0.04), transparent 42%), var(--card-bg-color, #fff);
            cursor: pointer;
            transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
        }

        .teacher-package-select:hover {
            transform: translateY(-6px);
            box-shadow: 0 24px 45px rgba(37, 99, 235, 0.14);
            border-color: rgba(37, 99, 235, 0.28);
        }

        .teacher-package-select.is-selected {
            border-color: #2563eb;
            box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
        }

        .teacher-package-select input {
            display: none;
        }

        .teacher-package-select__code {
            display: inline-flex;
            padding: 0.42rem 0.78rem;
            border-radius: 999px;
            background: rgba(37, 99, 235, 0.1);
            color: #2563eb;
            font-size: 0.78rem;
            font-weight: 700;
        }

        .teacher-package-select__price {
            display: block;
            margin-top: 0.75rem;
            font-size: 1.45rem;
            font-weight: 800;
        }

        .teacher-package-select__desc {
            margin-top: 0.85rem;
            color: var(--text-color-muted, #64748b);
        }

        .teacher-package-select__list {
            margin: 1rem 0 0;
            padding-left: 1rem;
            display: grid;
            gap: 0.4rem;
        }

        .teacher-payment-coupon .input-group-text {
            background: rgba(37, 99, 235, 0.08);
            border-color: rgba(37, 99, 235, 0.12);
            color: #2563eb;
            font-weight: 700;
        }

        .teacher-payment-summary {
            display: grid;
            gap: 0.7rem;
            margin-bottom: 1rem;
            padding: 1rem 1.1rem;
            border-radius: 20px;
            background: rgba(37, 99, 235, 0.06);
        }

        .teacher-payment-summary > div {
            display: flex;
            justify-content: space-between;
            gap: 1rem;
            align-items: center;
        }

        .teacher-payment-summary__total {
            padding-top: 0.7rem;
            border-top: 1px dashed rgba(37, 99, 235, 0.22);
        }

        .teacher-payment-badge,
        .teacher-coupon-chip {
            display: inline-flex;
            align-items: center;
            gap: 0.55rem;
            padding: 0.45rem 0.85rem;
            border-radius: 999px;
            font-weight: 700;
            font-size: 0.82rem;
        }

        .teacher-coupon-chip {
            background: rgba(37, 99, 235, 0.1);
            color: #1d4ed8;
        }

        .teacher-coupon-chip .btn-link {
            color: inherit;
            text-decoration: none;
            font-weight: 700;
        }

        .teacher-coupon-feedback {
            padding: 0.85rem 1rem;
            border-radius: 16px;
            font-weight: 600;
        }

        .teacher-coupon-feedback--success {
            background: rgba(34, 197, 94, 0.12);
            color: #15803d;
            border: 1px solid rgba(34, 197, 94, 0.18);
        }

        .teacher-coupon-feedback--error {
            background: rgba(239, 68, 68, 0.12);
            color: #b91c1c;
            border: 1px solid rgba(239, 68, 68, 0.18);
        }

        .teacher-payment-option {
            padding: 0.95rem 1rem;
            border-radius: 18px;
            border: 1px solid rgba(37, 99, 235, 0.12);
            margin-bottom: 0.75rem;
        }

        .teacher-payment-option.is-disabled {
            opacity: 0.55;
        }

        .teacher-payment-option label {
            display: flex;
            align-items: center;
            gap: 0.7rem;
            font-weight: 600;
            cursor: pointer;
        }

        .teacher-payment-panel {
            padding: 1rem 1.1rem;
            border-radius: 18px;
            background: rgba(37, 99, 235, 0.06);
        }

        .teacher-payment-qr {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 0.85rem;
            text-align: center;
        }

        .teacher-payment-qr img {
            display: block;
            width: min(100%, 220px);
            padding: 0.6rem;
            border-radius: 20px;
            background: #fff;
            box-shadow: 0 18px 40px rgba(15, 23, 42, 0.12);
        }

        .teacher-payment-qr__actions {
            display: flex;
            justify-content: center;
        }

        .teacher-payment-badge {
            display: inline-flex;
            align-items: center;
            padding: 0.45rem 0.85rem;
            border-radius: 999px;
            background: rgba(20, 184, 166, 0.14);
            color: #0f766e;
            font-weight: 700;
            font-size: 0.82rem;
        }

        .teacher-submit-btn {
            min-width: 220px;
            min-height: 52px;
            font-weight: 700;
        }
    </style>
@endsection

@section('scripts')
    <script>
        (() => {
            const packageInputs = document.querySelectorAll('input[name="package_id"]');
            const paymentMethods = document.querySelector('[data-payment-methods]');
            const freeBadge = document.querySelector('[data-free-badge]');
            const paymentPanels = document.querySelectorAll('[data-payment-panel]');
            const basePriceEl = document.querySelector('[data-base-price]');
            const discountPriceEl = document.querySelector('[data-discount-price]');
            const payablePriceEl = document.querySelector('[data-payable-price]');
            const qrImage = document.querySelector('[data-bank-qr]');
            const couponInput = document.querySelector('input[name="coupon_code"]');
            const couponChip = document.querySelector('[data-coupon-chip]');
            const couponChipCode = document.querySelector('[data-coupon-chip-code]');
            const couponSuccess = document.querySelector('[data-coupon-success]');
            const couponError = document.querySelector('[data-coupon-error]');
            const downloadQrButton = document.querySelector('[data-download-qr]');
            const transferContentEl = document.querySelector('[data-transfer-content]');
            const copyTransferButton = document.querySelector('[data-copy-transfer]');
            const copyButtons = document.querySelectorAll('[data-copy-trigger]');
            const copyFeedback = document.querySelector('[data-copy-feedback]');
            const countdownWrapper = document.querySelector('[data-countdown-wrapper]');
            const countdownText = document.querySelector('[data-countdown-text]');
            const qrBase = @json("https://img.vietqr.io/image/{$bankTransferBankBin}-{$bankTransferAccountNumber}-compact2.jpg");
            let appliedDiscount = Number(@json($selectedDiscountAmount));
            let countdownEndsAt = @json($countdownEndsAt);

            const formatMoney = (value) => new Intl.NumberFormat('vi-VN').format(Math.max(Number(value || 0), 0)) + 'd';
            const activePackage = () => document.querySelector('input[name="package_id"]:checked');
            const getTransferContent = () => {
                const packageCode = activePackage()?.dataset.packageCode || 'REGISTER';
                const couponCode = couponInput?.value?.trim().toUpperCase() || 'NEW';
                return `GV ${packageCode} ${couponCode}`.trim();
            };

            const showCopyFeedback = (message) => {
                if (!copyFeedback) {
                    return;
                }
                copyFeedback.textContent = message;
                copyFeedback.classList.remove('d-none');
                clearTimeout(showCopyFeedback.timer);
                showCopyFeedback.timer = setTimeout(() => copyFeedback.classList.add('d-none'), 2200);
            };

            const updateCouponUi = () => {
                const code = couponInput?.value?.trim().toUpperCase() || '';
                const hasCoupon = Boolean(code) && appliedDiscount > 0;
                couponChip?.classList.toggle('d-none', !hasCoupon);
                if (couponChipCode) {
                    couponChipCode.textContent = code;
                }
                if (!hasCoupon) {
                    couponSuccess?.classList.add('d-none');
                }
            };

            const updateCountdownVisibility = () => {
                const price = Number(activePackage()?.dataset.packagePrice || 0);
                countdownWrapper?.classList.toggle('d-none', !(price > 0 && countdownEndsAt));
            };

            const updateSummary = () => {
                const currentPackage = activePackage();
                const price = Number(currentPackage?.dataset.packagePrice || 0);
                const isFree = price <= 0;
                const discount = isFree ? 0 : appliedDiscount;
                const payable = Math.max(price - discount, 0);

                document.querySelectorAll('[data-package-card]').forEach((card) => card.classList.remove('is-selected'));
                currentPackage?.closest('[data-package-card]')?.classList.add('is-selected');
                paymentMethods?.classList.toggle('d-none', isFree);
                freeBadge?.classList.toggle('d-none', !isFree);

                if (basePriceEl) {
                    basePriceEl.textContent = formatMoney(price);
                }
                if (discountPriceEl) {
                    discountPriceEl.textContent = '-' + formatMoney(discount);
                }
                if (discountHidden) {
                    discountHidden.value = discount;
                }
                if (payablePriceEl) {
                    payablePriceEl.textContent = formatMoney(payable);
                }

                const transferContent = getTransferContent();
                if (transferContentEl) {
                    transferContentEl.textContent = transferContent;
                }
                if (qrImage) {
                    qrImage.src = `${qrBase}?amount=${Math.round(payable)}&addInfo=${encodeURIComponent(transferContent)}`;
                }
                if (isFree) {
                    countdownEndsAt = null;
                }

                updateCouponUi();
                updateCountdownVisibility();
            };

            const showPaymentPanel = (method) => {
                paymentPanels.forEach((panel) => {
                    panel.classList.toggle('d-none', panel.dataset.paymentPanel !== method);
                });
            };

            const runCountdown = () => {
                if (!countdownWrapper || !countdownText) {
                    return;
                }

                const tick = () => {
                    if (!countdownEndsAt) {
                        countdownWrapper.classList.add('d-none');
                        return;
                    }

                    const diff = new Date(countdownEndsAt).getTime() - Date.now();
                    if (diff <= 0) {
                        countdownText.textContent = '00:00';
                        countdownWrapper.classList.remove('d-none');
                        countdownWrapper.classList.add('is-expired');
                        return;
                    }

                    countdownWrapper.classList.remove('is-expired');
                    const totalSeconds = Math.floor(diff / 1000);
                    countdownText.textContent = `${String(Math.floor(totalSeconds / 60)).padStart(2, '0')}:${String(totalSeconds % 60).padStart(2, '0')}`;
                };

                tick();
                setInterval(tick, 1000);
            };

            packageInputs.forEach((input) => {
                input.addEventListener('change', () => {
                    appliedDiscount = 0;
                    countdownEndsAt = null;
                    if (discountHidden) {
                        discountHidden.value = 0;
                    }
                    couponSuccess?.classList.add('d-none');
                    couponError?.classList.add('d-none');
                    updateSummary();
                });
            });

            document.querySelectorAll('input[name="payment_method"]').forEach((input) => {
                input.addEventListener('change', () => showPaymentPanel(input.value));
            });

            couponInput?.addEventListener('input', () => {
                couponSuccess?.classList.add('d-none');
                couponError?.classList.add('d-none');
                if (!couponInput.value.trim()) {
                    appliedDiscount = 0;
                    countdownEndsAt = null;
                    updateSummary();
                }
            });

            couponButton?.addEventListener('click', async () => {
                const packageId = activePackage()?.value;
                const couponCode = couponInput?.value?.trim() || '';
                const token = document.querySelector('input[name="_token"]')?.value;

                couponSuccess?.classList.add('d-none');
                couponError?.classList.add('d-none');

                if (!packageId || !couponCode) {
                    couponError.textContent = 'Vui long chon goi va nhap ma giam gia truoc khi ap dung.';
                    couponError.classList.remove('d-none');
                    return;
                }

                couponButton.disabled = true;
                try {
                    const response = await fetch(couponButton.dataset.previewUrl, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'X-CSRF-TOKEN': token,
                            'X-Requested-With': 'XMLHttpRequest',
                            Accept: 'application/json',
                        },
                        credentials: 'same-origin',
                        body: JSON.stringify({ package_id: packageId, coupon_code: couponCode }),
                    });

                    const payload = await response.json();
                    if (!response.ok || !payload.success) {
                        throw new Error(payload.message || 'Ma giam gia khong hop le.');
                    }

                    couponInput.value = payload.data.coupon_code || couponCode.toUpperCase();
                    appliedDiscount = Number(payload.data.discount_amount || 0);
                    countdownEndsAt = payload.data.expires_at || null;
                    updateSummary();
                    couponSuccess.textContent = `Da ap ma ${couponInput.value}. Ban duoc giam ngay ${formatMoney(appliedDiscount)} tren goi hien tai.`;
                    couponSuccess.classList.remove('d-none');
                } catch (error) {
                    appliedDiscount = 0;
                    countdownEndsAt = null;
                    updateSummary();
                    couponError.textContent = error.message || 'Ma giam gia khong hop le.';
                    couponError.classList.remove('d-none');
                } finally {
                    couponButton.disabled = false;
                }
            });

            clearCouponButton?.addEventListener('click', async () => {
                const token = document.querySelector('input[name="_token"]')?.value;
                clearCouponButton.disabled = true;
                couponError?.classList.add('d-none');
                try {
                    await fetch(clearCouponButton.dataset.clearUrl, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'X-CSRF-TOKEN': token,
                            'X-Requested-With': 'XMLHttpRequest',
                            Accept: 'application/json',
                        },
                        credentials: 'same-origin',
                        body: JSON.stringify({ clear: true }),
                    });
                } finally {
                    couponInput.value = '';
                    appliedDiscount = 0;
                    countdownEndsAt = null;
                    updateSummary();
                    clearCouponButton.disabled = false;
                }
            });

            copyButtons.forEach((button) => {
                button.addEventListener('click', async () => {
                    try {
                        await navigator.clipboard.writeText(button.dataset.copyTrigger || '');
                        showCopyFeedback('Da copy so tai khoan.');
                    } catch (error) {
                        showCopyFeedback('Khong copy tu dong duoc, ban copy tay giup minh nhe.');
                    }
                });
            });

            copyTransferButton?.addEventListener('click', async () => {
                try {
                    await navigator.clipboard.writeText(transferContentEl?.textContent?.trim() || '');
                    showCopyFeedback('Da copy noi dung chuyen khoan.');
                } catch (error) {
                    showCopyFeedback('Khong copy tu dong duoc, ban copy tay giup minh nhe.');
                }
            });

            downloadQrButton?.addEventListener('click', async () => {
                if (!qrImage?.src) {
                    return;
                }

                try {
                    const response = await fetch(qrImage.src, { mode: 'cors' });
                    const blob = await response.blob();
                    const blobUrl = URL.createObjectURL(blob);
                    const link = document.createElement('a');
                    link.href = blobUrl;
                    link.download = 'teacher-payment-qr.png';
                    document.body.appendChild(link);
                    link.click();
                    link.remove();
                    URL.revokeObjectURL(blobUrl);
                } catch (error) {
                    window.open(qrImage.src, '_blank', 'noopener');
                }
            });

            updateSummary();
            showPaymentPanel(document.querySelector('input[name="payment_method"]:checked')?.value || 'bank_transfer');
            runCountdown();
        })();
    </script>
@endsection
